  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0d1117;
      --panel: #161b22;
      --panel-soft: #1f2630;
      --text: #f0f6fc;
      --muted: #8b949e;
      --accent: #58a6ff;
      --accent-strong: #1f6feb;
      --error: #ff7b72;
      --border: #30363d;
      --focus: #79c0ff;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 2rem;
      background:
        radial-gradient(circle at top left, rgba(88, 166, 255, 0.18), transparent 32rem),
        linear-gradient(135deg, #090c10 0%, var(--bg) 55%, #101620 100%);
      color: var(--text);
      font-family: Arial, Helvetica, sans-serif;
      line-height: 1.5;
    }

    main {
      width: min(100%, 34rem);
    }

    .support-card {
      padding: clamp(1.5rem, 5vw, 2.5rem);
      background: rgba(22, 27, 34, 0.9);
      border: 1px solid var(--border);
      border-radius: 1.25rem;
      box-shadow: 0 1.5rem 4rem rgba(0, 0, 0, 0.35);
      backdrop-filter: blur(18px);
    }

    h1 {
      margin: 0 0 0.5rem;
      font-size: clamp(2rem, 6vw, 3rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 2rem;
      color: var(--muted);
    }

    .form-field {
      margin-bottom: 1.25rem;
    }

    label {
      display: block;
      margin-bottom: 0.45rem;
      font-weight: 700;
    }

    input {
      width: 100%;
      min-height: 3rem;
      padding: 0.75rem 0.9rem;
      border: 1px solid var(--border);
      border-radius: 0.75rem;
      background: var(--panel-soft);
      color: var(--text);
      font: inherit;
      transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
    }

    input::placeholder {
      color: #6e7681;
    }

    input:focus {
      border-color: var(--focus);
      box-shadow: 0 0 0 0.2rem rgba(88, 166, 255, 0.22);
      outline: none;
    }

    input[aria-invalid="true"] {
      border-color: var(--error);
    }

    .helper-text {
      margin: 0.4rem 0 0;
      color: var(--muted);
      font-size: 0.92rem;
    }

    .validation-message {
      min-height: 1.35rem;
      margin: 0.35rem 0 0;
      color: var(--error);
      font-size: 0.92rem;
    }

    .validation-message:empty {
      display: none;
    }

    button {
      width: 100%;
      min-height: 3rem;
      margin-top: 0.5rem;
      border: 0;
      border-radius: 0.75rem;
      background: linear-gradient(135deg, var(--accent), var(--accent-strong));
      color: #ffffff;
      cursor: pointer;
      font: inherit;
      font-weight: 700;
      transition: filter 160ms ease, transform 160ms ease;
    }

    button:hover {
      filter: brightness(1.08);
    }

    button:focus {
      outline: 0.2rem solid var(--focus);
      outline-offset: 0.2rem;
    }

    button:active {
      transform: translateY(1px);
    }

    .success-message {
      margin: 1rem 0 0;
      color: #7ee787;
      font-weight: 700;
    }

    .success-message:empty {
      display: none;
    }
  </style>
</head>
<body>
  <main>
    <section class="support-card" aria-labelledby="support-title">
      <h1 id="support-title">Contact support</h1>
      <p class="intro">Tell us how to reach you, and our support team will follow up shortly.</p>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">Full name <span aria-hidden="true">*</span></label>
          <input
            type="text"
            id="full-name"
            name="fullName"
            autocomplete="name"
            required
            aria-required="true"
            aria-describedby="full-name-error"
          >
          <p class="validation-message" id="full-name-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="email">Email address <span aria-hidden="true">*</span></label>
          <input
            type="email"
            id="email"
            name="email"
            autocomplete="email"
            required
            aria-required="true"
            aria-describedby="email-error"
          >
          <p class="validation-message" id="email-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="phone">Phone number</label>
          <input
            type="tel"
            id="phone"
            name="phone"
            autocomplete="tel"
            inputmode="tel"
            aria-describedby="phone-helper phone-error"
          >
          <p class="helper-text" id="phone-helper">Use international format, for example +1 555 123 4567.</p>
          <p class="validation-message" id="phone-error" aria-live="polite"></p>
        </div>

        <button type="submit">Submit request</button>
        <p class="success-message" id="success-message" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#support-form");
    const successMessage = document.querySelector("#success-message");
    const fields = {
      fullName: {
        input: document.querySelector("#full-name"),
        error: document.querySelector("#full-name-error"),
        validate(value) {
          return value.trim() ? "" : "Enter your full name.";
        }
      },
      email: {
        input: document.querySelector("#email"),
        error: document.querySelector("#email-error"),
        validate(value) {
          if (!value.trim()) {
            return "Enter your email address.";
          }

          return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())
            ? ""
            : "Enter a valid email address.";
        }
      },
      phone: {
        input: document.querySelector("#phone"),
        error: document.querySelector("#phone-error"),
        validate(value) {
          if (!value.trim()) {
            return "";
          }

          return /^\+?[0-9\s().-]{7,20}$/.test(value.trim())
            ? ""
            : "Enter a phone number using digits and optional spaces, dashes, parentheses, or a leading plus sign.";
        }
      }
    };

    function setFieldError(field, message) {
      field.error.textContent = message;
      field.input.setAttribute("aria-invalid", message ? "true" : "false");
    }

    function validateField(field) {
      const message = field.validate(field.input.value);
      setFieldError(field, message);
      return !message;
    }

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      successMessage.textContent = "";

      const isValid = Object.values(fields).every(validateField);
      if (!isValid) {
        return;
      }

      form.reset();
      Object.values(fields).forEach((field) => setFieldError(field, ""));
      successMessage.textContent = "Thanks. Your support request is ready to send.";
    });

    Object.values(fields).forEach((field) => {
      field.input.addEventListener("input", () => {
        if (field.input.getAttribute("aria-invalid") === "true") {
          validateField(field);
        }
      });
    });
  </script>
</body>
</html>
